function parseDataView(view){
  if(!view || !view.table || !view.table.columns || !view.table.rows) return null;
  var roles=["month", "country", "country_name", "region_group", "product", "exposure", "npl", "ecl", "stage2", "stage3", "dpd30", "scheduled", "received", "loans"];
  var index={};
  view.table.columns.forEach(function(c,i){
    if(!c.roles)return;
    roles.forEach(function(r){if(c.roles[r])index[r]=i;});
  });
  if(roles.some(function(r){return index[r]===undefined;}))return null;
  var metrics=['exposure','npl','ecl','stage2','stage3','dpd30','scheduled','received','loans'];
  var out=[];
  view.table.rows.forEach(function(row){
     var rec={};roles.forEach(function(r){rec[r]=row[index[r]];});
     rec.date=rec.month;
     delete rec.month;
     if(rec.date instanceof Date)rec.date=rec.date.getFullYear()+'-'+String(rec.date.getMonth()+1).padStart(2,'0');
     metrics.forEach(function(k){rec[k]=Number(rec[k])||0;});
     if(rec.date&&rec.country&&rec.product)out.push(rec);
  });
  return out;
}
