const frac=(a,b)=>b>0?a/b:0;
const monthsIncluded=()=>MONTHS.slice(-state.period);
function baseSlice(date=LATEST,{allCountries=false}={}){
 return DB.fact.filter(r=>r.date===date && (state.product==='All'||r.product===state.product) && (allCountries||((state.region==='Global'||r.region_group===state.region)&&(!state.country||r.country===state.country))));
}
function agg(rows){let o={};['exposure','npl','ecl','stage2','stage3','dpd30','scheduled','received','loans'].forEach(k=>o[k]=sum(rows,k));o.nplRatio=100*frac(o.npl,o.exposure);o.eclRatio=100*frac(o.ecl,o.exposure);o.stageRatio=100*frac(o.stage2+o.stage3,o.exposure);o.collect=100*frac(o.received,o.scheduled);o.coverage=100*frac(o.ecl,o.npl);return o}
function snapshot(d=LATEST){return agg(baseSlice(d))}
function trend(){return monthsIncluded().map(d=>({date:d,...snapshot(d)}))}
function countryCountTrend(){return monthsIncluded().map(d=>new Set(baseSlice(d,{allCountries:true}).map(r=>r.country)).size)}
function topShareTrend(){return monthsIncluded().map(d=>{let rows=baseSlice(d,{allCountries:true});let total=sum(rows,'exposure');let by=new Map();for(const r of rows)by.set(r.country,(by.get(r.country)||0)+(r.exposure||0));let top=Math.max(0,...by.values());return total?100*top/total:0})}
function mom(k){let cur=snapshot(),prev=snapshot(MONTHS.at(-2));return prev[k]?100*(cur[k]-prev[k])/prev[k]:0}
function rowsByCountry({respectRegion=true}={}){
 let a=baseSlice(LATEST,{allCountries:true});if(respectRegion && state.region!=='Global')a=a.filter(r=>r.region_group===state.region);
 let m=new Map();for(const r of a){let prev=m.get(r.country);if(!prev){prev={iso:r.country,name:r.country_name,region:r.region_group,exposure:0,npl:0,ecl:0,loans:0,stage2:0,stage3:0};m.set(r.country,prev)}for(const k of ['exposure','npl','ecl','loans','stage2','stage3'])prev[k]+=r[k]||0}
 return [...m.values()].map(x=>({...x,nplRatio:100*frac(x.npl,x.exposure),eclRatio:100*frac(x.ecl,x.exposure)}));
}
function rowsByProduct(){return DB.domestic.products.map((p,i)=>({name:p,color:COLORS[i],...agg(baseSlice(LATEST).filter(r=>r.product===p))}));}
function euroDelta(v){return (v>=0?'+':'')+pc(v)}
const PANEL=(title,desc,children,cls='',extra='')=>`<article class="panel ${cls}"><header class="panel-header"><div><h2 class="panel-title">${title}</h2><p class="panel-subtitle">${desc}</p></div>${extra}</header>${children}</article>`;
function refinedSpark(values,color,title,comparison='historical'){
 const v=(values||[]).filter(Number.isFinite);if(v.length<2)return '<div class="kpi-series-empty">Not enough observations</div>';
 const W=200,H=57,L=5,R=7,T=7,B=6;
 const lo0=Math.min(...v),hi0=Math.max(...v),padding=(hi0-lo0)*.18||Math.abs(lo0)*.05||1;
 const lo=lo0-padding,hi=hi0+padding;
 const x=i=>L+i*(W-L-R)/(v.length-1),y=z=>T+(hi-z)/(hi-lo)*(H-T-B);
 const coords=v.map((z,i)=>[x(i),y(z)]);
 let path=`M ${coords[0][0].toFixed(2)} ${coords[0][1].toFixed(2)}`;
 for(let i=1;i<coords.length;i++){
   const p=coords[i-1],q=coords[i],d=(q[0]-p[0])*.34;
   path+=` C ${(p[0]+d).toFixed(2)} ${p[1].toFixed(2)}, ${(q[0]-d).toFixed(2)} ${q[1].toFixed(2)}, ${q[0].toFixed(2)} ${q[1].toFixed(2)}`;
 }
 const area=path+` L ${x(v.length-1).toFixed(2)} ${H-B} L ${x(0).toFixed(2)} ${H-B} Z`;
 const key=title.toLowerCase().replace(/[^a-z0-9]+/g,'-');
 const end=coords.at(-1),first=coords[0];
 const d=monthsIncluded(), startDate=d[0]||LATEST, endDate=d.at(-1)||LATEST;
 const fmtMonth=date=>{let [yr,mo]=date.split('-').map(Number);return new Date(Date.UTC(yr,mo-1,1)).toLocaleDateString('en-GB',{month:'short',year:'2-digit'}).toUpperCase().replace(' ',' ‘');};
 const startLabel=comparison==='scenario'?'REFERENCE':fmtMonth(startDate), endLabel=comparison==='scenario'?'STRESSED':fmtMonth(endDate);
 const plotted=(v.length>12?v.filter((_,i)=>i%2===0||i===v.length-1):v);
 return `<div class="kpi-spark-advanced" style="--trend-color:${color}" aria-label="${comparison==='scenario'?'Scenario comparison':'Historical series from '+startLabel+' to '+endLabel}">
   <div class="kpi-trend-head"><span>${comparison==='scenario'?'SCENARIO BRIDGE':v.length+' MONTHS · MONTH-END'}</span><span class="kpi-trend-mark">${comparison==='scenario'?'SIMULATED':'HISTORICAL'}</span></div>
   <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${title} ${comparison==='scenario'?'scenario comparison':'monthly evolution'}">
     <defs><linearGradient id="hbc-grad-${key}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".23"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>
     <path d="M${L} ${H-B}H${W-R}" stroke="#dce5e3" stroke-width=".8" fill="none"/>
     <path d="${area}" fill="url(#hbc-grad-${key})"/>
     <path d="${path}" fill="none" stroke="${color}" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>
     <circle cx="${first[0]}" cy="${first[1]}" r="2.0" fill="#fbfaf8" stroke="${color}" stroke-width="1.2" vector-effect="non-scaling-stroke"/>
     <circle cx="${end[0]}" cy="${end[1]}" r="3.25" fill="${color}" stroke="#fcfbf9" stroke-width="1.5" vector-effect="non-scaling-stroke"/>
     ${v.map((z,i)=>`<circle cx="${x(i).toFixed(2)}" cy="${y(z).toFixed(2)}" r="5" fill="transparent"><title>${comparison==='scenario'?(i?'Stressed':'Reference'):d[i]||'Observation '+(i+1)}: ${title.toLowerCase().includes('ratio')||title.toLowerCase().includes('coverage')||title.toLowerCase().includes('collection')||title.toLowerCase().includes('dpd')||title.includes('Stage')||title.includes('impact')?pc(z):money(z)}</title></circle>`).join('')}
   </svg>
   <div class="kpi-period-ends"><span>${startLabel}</span><span>${endLabel}</span></div>
 </div>`;
}
function kpiCard(title,value,sub,delta=null,symbol='↗',spark=[],color='#718d96',kind='historical'){
 const v=(spark||[]).filter(Number.isFinite);
 const change=v.length>1?v.at(-1)-v.at(-2):null;
 const isRatio=title.toLowerCase().includes('ratio')||title.toLowerCase().includes('coverage')||title.toLowerCase().includes('collection')||title.includes('Stage')||title.includes('DPD')||title.toLowerCase().includes('cost of risk')||title.toLowerCase().includes('impact')||title.toLowerCase().includes('concentration');
 const isCount=title.toLowerCase().includes('countr');
 const momText=kind==='scenario'? 'Scenario-adjusted illustration'
 :delta!==null?`${delta>=0?'+':''}${num(delta,1)}% MoM`
 :change!==null&&!isCount?(isRatio?`${change>=0?'+':''}${num(change,1)} pp MoM`:`${change>=0?'+':''}${pc(v.at(-2)?change/v.at(-2)*100:0)} MoM`):'Latest month-end snapshot';
 const riskWorsens=title.toLowerCase().includes('npl')||title.toLowerCase().includes('dpd')||title.toLowerCase().includes('expected credit loss')||title.toLowerCase().includes('stage')||title.toLowerCase().includes('cost of risk');
 const isPos=change!==null?change>0:delta!==null?delta>0:false;
 const tone=kind==='scenario'?'neutral':isCount?'neutral':(riskWorsens?(isPos?'adverse':'positive'):title.toLowerCase().includes('collection')?(isPos?'positive':'adverse'):'neutral');
 const unit=value.indexOf('€')!==-1?'EUR':value.includes('%')?'PERCENT':'MARKETS';
 const chartKind=kind==='scenario'?'scenario':'historical';
 const series=v.length>1?refinedSpark(v,color,title,chartKind):`<div class="kpi-context-only"><span>GLOBAL PERIMETER</span><strong>${sub}</strong></div>`;
 return `<article class="kpi kpi-refined" style="--kpi-accent:${color}">
   <div class="kpi-copy">
     <div class="kpi-heading"><span>${title}</span><span class="kpi-unit">${unit}</span></div>
     <div class="kpi-primary">${value}</div>
     <div class="kpi-descriptor">${sub}</div>
     <div class="kpi-comparison ${tone}"><span class="kpi-comparison-rule"></span>${momText}</div>
   </div>${series}
 </article>`;
}
const xy=(v,lo,hi,x0,w)=>x0+(hi>lo?(v-lo)/(hi-lo):.5)*w;
function lineChart(dat,key1,key2,label1,label2,unit1='money',unit2='money') {
 const W=1000,H=192,p={l:56,r:62,t:12,b:30};if(!dat.length)return '';
 const a=dat.map(r=>r[key1]||0),b=dat.map(r=>r[key2]||0),maxA=Math.max(...a,1)*1.13,maxB=Math.max(...b,1)*1.13;
 const x=i=>p.l+i*(W-p.l-p.r)/Math.max(1,dat.length-1),y1=v=>H-p.b-v/maxA*(H-p.b-p.t),y2=v=>H-p.b-v/maxB*(H-p.b-p.t);
 const path=(arr,fn)=>arr.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+fn(v).toFixed(1)).join(' ');
 const d1=path(a,y1), d2=path(b,y2), grid=[0,.25,.5,.75,1].map(i=>{let y=H-p.b-i*(H-p.b-p.t);return `<line x1="${p.l}" x2="${W-p.r}" y1="${y}" y2="${y}" class="gridline"/><text x="${p.l-8}" y="${y+4}" text-anchor="end" class="axis">${unit1==='money'?money(maxA*i,0):pc(maxA*i,0)}</text><text x="${W-p.r+8}" y="${y+4}" class="axis">${unit2==='money'?money(maxB*i,0):pc(maxB*i,0)}</text>`}).join('');
 const lbl=dat.map((r,i)=>i%Math.max(1,Math.ceil(dat.length/6))===0||i===dat.length-1?`<text x="${x(i)}" y="${H-5}" text-anchor="middle" class="axis">${r.date.slice(5)}/${r.date.slice(2,4)}</text>`:'').join('');
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${label1} and ${label2}">${grid}<path d="${d1} L${x(dat.length-1)},${H-p.b} L${x(0)},${H-p.b} Z" class="line-area"/><path d="${d1}" class="line-a"/><path d="${d2}" class="line-b"/>${lbl}</svg>`;
}
function gauge(value,max,label,color){let r=27,percent=Math.max(0,Math.min(1,frac(value,max))),cir=2*Math.PI*r;return `<svg class="meter-svg" viewBox="0 0 70 70" role="img" aria-label="${label}: ${pc(value)}"><circle cx="35" cy="35" r="27" stroke="#e4e9e7" stroke-width="6" fill="none"/><circle cx="35" cy="35" r="27" stroke="${color}" stroke-width="6" fill="none" stroke-dasharray="${cir*percent} ${cir*(1-percent)}" stroke-linecap="round" transform="rotate(-90 35 35)"/></svg>`}
function statusPanel(m){
 const stage1=Math.max(0,m.exposure-m.stage2-m.stage3),tot=m.exposure||1;
 const prior=snapshot(MONTHS.at(-2));
 const meters=[
  ['NPL ratio',m.nplRatio,prior.nplRatio,15,'#547e87','NPL over EAD',true],
  ['Collections',m.collect,prior.collect,100,'#4e8179','Received / planned',false],
  ['Coverage',m.coverage,prior.coverage,100,'#916a76','ECL over NPL',false],
  ['Deteriorated exposure',m.stageRatio,prior.stageRatio,40,'#718ea0','Stages 2 and 3',true]
 ];
 return PANEL('Quality indicators','Month-end asset quality and collections',`<div class="meter-row">${meters.map(([label,value,prev,max,color,note,badUp])=>{
  const diff=value-prev;
  const arrow=Math.abs(diff)<.05?'→':diff>0?'↑':'↓';
  const tone=Math.abs(diff)<.05?'neutral':(badUp?(diff>0?'adverse':'favourable'):(diff>0?'favourable':'adverse'));
  return `<div class="meter-card">${gauge(value,max,label,color)}<div class="meter-body"><div class="meter-label">${label}</div><div class="meter-value">${pc(value)}</div><div class="meter-note">${note}</div><div class="meter-movement ${tone}">${arrow} ${diff>=0?'+':''}${num(diff,1)} pp <span>vs prior month</span></div></div></div>`;
 }).join('')}</div><div class="stage-head"><span>Stage distribution</span><span>${money(m.exposure,1)} EAD</span></div><div class="stack"><div style="width:${100*frac(stage1,tot)}%;background:#568279"></div><div style="width:${100*frac(m.stage2,tot)}%;background:#9da9ab"></div><div style="width:${100*frac(m.stage3,tot)}%;background:#9b6f7c"></div></div><div class="stage-labels"><span><i style="background:#568279"></i>Stage 1 ${pc(100*frac(stage1,tot),0)}</span><span><i style="background:#9da9ab"></i>Stage 2 ${pc(100*frac(m.stage2,tot),0)}</span><span><i style="background:#9b6f7c"></i>Stage 3 ${pc(100*frac(m.stage3,tot),0)}</span></div>`,'status-panel');
}

function metricVal(r){return state.mapMetric==='nplRatio'?r.nplRatio:state.mapMetric==='ecl'?r.ecl:r.exposure}
function metricLabel(){return state.mapMetric==='nplRatio'?'NPL':state.mapMetric==='ecl'?'ECL':'Exposure'}
function metricFormat(v){return state.mapMetric==='nplRatio'?pc(v,1):money(v,1)}
function colorRamp(t){t=Math.max(0,Math.min(1,t));let stops=state.mapMetric==='nplRatio'?[[226,221,222],[196,174,180],[161,132,145],[133,98,111]]:[[223,230,228],[174,195,196],[100,139,152],[54,90,108]];let v=t*3,i=Math.min(2,Math.floor(v)),z=v-i,lo=stops[i],hi=stops[i+1];return '#'+lo.map((x,k)=>Math.round(x*(1-z)+hi[k]*z).toString(16).padStart(2,'0')).join('')}
function worldMap(){let rows=rowsByCountry();let byIso=Object.fromEntries(rows.map(r=>[r.iso,r]));let values=rows.map(metricVal),sorted=[...rows].sort((a,b)=>metricVal(b)-metricVal(a)),min=Math.min(...values),max=Math.max(...values);
 const shapes=DB.geo.map(g=>{let r=byIso[g.iso],fill=r?colorRamp(frac(metricVal(r)-min,max-min)):'#e2e7e4';let selected=g.iso===state.country;return `<path class="country-shape ${selected?'selected':''}" data-country="${g.iso}" d="${g.path}" fill="${fill}" fill-rule="evenodd"><title>${esc(g.name)}${r?' · '+metricLabel()+': '+metricFormat(metricVal(r)):' · No exposure'}</title></path>`}).join('');
 const ctrls=['exposure','nplRatio','ecl'].map((v,i)=>`<button data-mapmetric="${v}" class="${state.mapMetric===v?'on':''}">${['Exposure','NPL %','ECL'][i]}</button>`).join('');
 const legend=Array.from({length:7},(_,i)=>`<span style="background:${colorRamp(i/6)}"></span>`).join('');
 const ranking=sorted.slice(0,4).map((r,i)=>`<button class="country-rank ${state.country===r.iso?'active':''}" data-country="${r.iso}"><span><span>${i+1}. ${esc(r.name)}</span><b>${metricFormat(metricVal(r))}</b></span><small>NPL ${pc(r.nplRatio)} · EAD ${money(r.exposure)}</small></button>`).join('');
 return PANEL('Geographic concentration','Distribution by country for the selected metric; click a country to filter the dashboard',`<div class="map-layout"><div class="map-main"><div class="map-box"><svg class="country-map" viewBox="0 28 900 335" preserveAspectRatio="xMidYMid meet" role="img" aria-label="World choropleth map with real geographic boundaries">${shapes}</svg></div><div class="map-footer"><span>Countries with exposure: ${rows.length} · ${metricLabel()}</span><span class="scale">Low ${legend} High</span></div></div><div class="map-right"><div class="country-rank-title">HIGHEST CONCENTRATION</div>${ranking}<div class="map-metric">${ctrls}</div></div></div>`,'map-panel');}
function productPanel(){let rows=rowsByProduct(),tot=sum(rows,'exposure'),radius=76,C=2*Math.PI*radius;let start=0;
 const segs=rows.map((r,i)=>{let ratio=frac(r.exposure,tot),len=ratio*C,part=`<circle r="${radius}" cx="110" cy="110" stroke="${COLORS[i]}" stroke-width="31" fill="none" stroke-dasharray="${Math.max(0,len-2)} ${C}" stroke-dashoffset="${-start}" transform="rotate(-90 110 110)"><title>${esc(r.name)} ${pc(100*ratio)}</title></circle>`;start+=len;return part}).join('');
 return PANEL('Product mix','Share of total outstanding balance',`<div class="donut-layout"><svg class="donut-svg" viewBox="0 0 220 220" aria-label="Product percentage distribution" role="img"><circle r="76" cx="110" cy="110" fill="none" stroke="#e4e8e6" stroke-width="31"/>${segs}<text x="110" y="105" text-anchor="middle" class="donut-centre">${money(tot,0)}</text><text x="110" y="122" text-anchor="middle" class="donut-small">TOTAL PORTFOLIO</text></svg><div class="donut-list">${rows.map((r,i)=>{let f=frac(r.exposure,tot);return `<div class="donut-row"><span class="dot" style="--color:${COLORS[i]}"></span><div>${r.name}<small>${pc(100*f)} of portfolio</small></div><div class="donut-val">${money(r.exposure)}</div></div>`}).join('')}</div></div><p class="donut-note">Amounts and percentages use the same filter scope.</p>`,'portfolio-panel');}
function overview(){let m=snapshot(),tr=trend();return `<div class="grid kpi-grid">${kpiCard('Gross exposure',money(m.exposure),'Total outstanding balance',mom('exposure'),'↗',tr.map(r=>r.exposure),'#6f8a93')}${kpiCard('Expected credit loss',money(m.ecl),'Cost of risk '+pc(m.eclRatio),mom('ecl'),'◈',tr.map(r=>r.ecl),'#a07a85')}${kpiCard('NPL ratio',pc(m.nplRatio),'Non-performing loans',null,'○',tr.map(r=>r.nplRatio),'#738a9f')}${kpiCard('Collection efficiency',pc(m.collect),'Collections versus plan',null,'↗',tr.map(r=>r.collect),'#5f887c')}</div><div class="grid content-grid">${PANEL('Exposure and expected loss','Monthly trend · exposure on the left axis and expected loss on the right axis',`<div class="legend"><span class="legend-key" style="--key:#476879">Exposure</span><span class="legend-key" style="--key:#916473">Expected loss</span></div><div class="chart-body">${lineChart(tr,'exposure','ecl','EAD','ECL')}</div>`,'chart-panel')}${statusPanel(m)}</div><div class="grid map-grid">${worldMap()}${productPanel()}</div>`}
function rankPanel(){let a=rowsByCountry().sort((x,y)=>y.exposure-x.exposure),m=Math.max(...a.map(r=>r.exposure),1);return PANEL('Top markets','Exposure by country in the latest snapshot',`<div class="breakdown">${a.slice(0,8).map(r=>`<div class="breakdown-row"><span>${esc(r.name)}</span><span class="num">${money(r.exposure)}</span><span class="breakdown-track"><span style="width:${100*r.exposure/m}%"></span></span></div>`).join('')}</div>`,'large-panel')}
function riskColor(t){t=Math.max(0,Math.min(1,t));let a=[211,226,222],b=[140,91,108];return '#'+a.map((v,i)=>Math.round(v*(1-t)+b[i]*t).toString(16).padStart(2,'0')).join('')}
function riskMatrix(){let regions=(state.region==='Global'?['Americas','EMEA','APAC']:[state.region]),products=(state.product==='All'?DB.domestic.products:[state.product]),vals=[];let mat=regions.map(reg=>products.map(p=>{let a=agg(DB.fact.filter(r=>r.date===LATEST && r.region_group===reg && r.product===p));let v=a.nplRatio;vals.push(v);return v}));let min=Math.min(...vals),max=Math.max(...vals);
 return PANEL('Risk matrix','Exposure-weighted NPL ratio · colour represents risk, not balance',`<table class="matrix"><thead><tr><th></th>${products.map(p=>`<th>${esc(p)}</th>`).join('')}</tr></thead><tbody>${regions.map((reg,i)=>`<tr><td class="rowhead">${reg}</td>${mat[i].map(v=>{let color=riskColor(frac(v-min,max-min));return `<td style="background:${color};color:${v>max*.77?'#fff':'#203f4e'}">${pc(v)}</td>`}).join('')}</tr>`).join('')}</tbody></table><div class="region-summary">${regions.map(reg=>{let m=agg(DB.fact.filter(r=>r.date===LATEST&&r.region_group===reg&&(state.product==='All'||r.product===state.product)));return `<div><span>${reg}</span><b>${money(m.exposure)} EAD</b><small>NPL ${pc(m.nplRatio)}</small></div>`}).join('')}</div>`,'large-panel');}
function segmentPanel(){let a=rowsByCountry().sort((x,y)=>y.nplRatio-x.nplRatio).slice(0,8),max=Math.max(...a.map(r=>r.nplRatio),1);return PANEL('Risk by market','Highest NPL rates, excluding portfolio size effects',`<div class="breakdown">${a.map(r=>`<div class="breakdown-row"><span>${esc(r.name)}</span><span class="num">${pc(r.nplRatio)}</span><span class="breakdown-track"><span style="width:${100*r.nplRatio/max}%;background:#916c77"></span></span></div>`).join('')}</div>`,'large-panel')}
function gradePanel(){let profile=DB.grade.filter(r=>r.product===(state.product==='All'?'All':state.product));let amt=sum(profile,'exposure')||1,current=snapshot(),colors=['#486a78','#648594','#8da5a8','#a49b9e','#9f7582'];let grades=profile.map((r,i)=>({...r,share:frac(r.exposure,amt),estimatedExposure:r.exposure/amt*current.exposure,color:colors[i]}));return PANEL('Rating distribution','Synthetic credit-grade mix based on the source portfolio',`<div class="breakdown">${grades.map(r=>`<div class="breakdown-row"><span>Grade ${esc(r.grade)}</span><span class="num">${pc(r.share*100,0)}</span><span class="breakdown-track"><span style="width:${r.share/Math.max(...grades.map(x=>x.share))*100}%;background:${r.color}"></span></span></div>`).join('')}</div><div class="region-summary">${grades.slice(0,3).map(r=>`<div><span>Grade ${r.grade}</span><b>${money(r.estimatedExposure)}</b><small>Source NPL ${pc(r.npl_ratio,1)}</small></div>`).join('')}</div><p class="donut-note">For a selected country or region, the product rating mix is assumed to follow the same synthetic allocation.</p>`,'large-panel');}
function portfolio(){let m=snapshot(),concentration=rowsByCountry(),top=Math.max(...concentration.map(x=>x.exposure),0),tr=trend();return `<div class="grid kpi-grid">${kpiCard('Countries in portfolio',num(concentration.length,0),'Markets with exposure',null,'◎',[],'#7c9399')}${kpiCard('Largest concentration',pc(100*frac(top,m.exposure)),'Share of the top country',null,'◈',topShareTrend(),'#a07a85')}${kpiCard('Cost of risk',pc(m.eclRatio),'ECL / EAD',null,'○',tr.map(r=>r.eclRatio),'#738a9f')}${kpiCard('Stage 2 + 3',pc(m.stageRatio),'Deteriorated exposure',null,'▱',tr.map(r=>r.stageRatio),'#5f887c')}</div><div class="grid equal-grid">${rankPanel()}${riskMatrix()}</div><div class="grid equal-grid">${segmentPanel()}${gradePanel()}</div>`}
function vintages(){let arr=DB.domestic.vintages.filter(v=>v.region==='All'&&v.product===state.product).sort((a,b)=>a.vintage.localeCompare(b.vintage)),dates=[...new Set(arr.map(v=>v.vintage))].slice(-(window.innerHeight<=850?7:9)),vmap=new Map(arr.map(v=>[v.vintage+'|'+v.mob,v]));let cols=Array.from({length:10},(_,i)=>i),vals=arr.map(v=>v.npl_ratio),max=Math.max(...vals,1);return PANEL('Vintage performance','NPL ratio by months on books since origination; synthetic domestic sample',`<table class="matrix"><thead><tr><th>Vintage</th>${cols.map(m=>`<th>M${m}</th>`).join('')}</tr></thead><tbody>${dates.map(v=>`<tr><td class="rowhead">${v}</td>${cols.map(m=>{let x=vmap.get(v+'|'+m);if(!x)return `<td style="background:#edf0ee;color:#adb8bb">—</td>`;let n=x.npl_ratio,rat=Math.min(1,n/max),c=colorRamp(rat);return `<td style="background:${c};color:${rat>.65?'white':'#2b4d57'}">${pc(n)}</td>`}).join('')}</tr>`).join('')}</tbody></table>`,'large-panel')}
function quality(){let tr=trend().map(r=>({...r,dpd:100*frac(r.dpd30,r.exposure)})),m=snapshot();return `<div class="grid kpi-grid">${kpiCard('DPD 30+',pc(100*frac(m.dpd30,m.exposure)),'Portfolio ≥ 30 days past due',null,'○',tr.map(r=>r.dpd),'#7a8fa0')}${kpiCard('Non-performing loans',money(m.npl),'Defaulted exposure',null,'◈',tr.map(r=>r.npl),'#a07a85')}${kpiCard('Stage 2',money(m.stage2),'Significant increase in credit risk',null,'▱',tr.map(r=>r.stage2),'#95a3a4')}${kpiCard('Stage 3',money(m.stage3),'Deteriorated exposure',null,'▱',tr.map(r=>r.stage3),'#6f8b80')}</div><div class="grid content-grid">${PANEL('Monthly deterioration','DPD 30+ and NPL compared on a percentage basis',`<div class="legend"><span class="legend-key" style="--key:#476879">DPD 30+</span><span class="legend-key" style="--key:#916473">NPL</span></div><div class="chart-body">${lineChart(tr,'dpd','nplRatio','DPD 30+','NPL','pct','pct')}</div>`,'chart-panel')}${statusPanel(m)}</div><div class="grid">${vintages()}</div>`}
const scenarios={Baseline:{pd:1,lgd:1,label:'No shock'},Adverse:{pd:1.25,lgd:1.12,label:'Economic slowdown and moderate deterioration'},Severe:{pd:1.65,lgd:1.28,label:'Severe downturn and weaker recoveries'}};
// Dynamic stress-risk visual layer: exact reconciliations, no mocked chart numbers.
function stressFactor(s){return s.pd*s.lgd;}
function scenarioImpactParts(base,s){return [
 {key:'pd',label:'PD uplift',amount:base*(s.pd-1),tone:'increase'},
 {key:'lgd',label:'LGD uplift',amount:base*s.pd*(s.lgd-1),tone:'increase'}
];}
function stressSegments(){
 const products=rowsByProduct(),tot=products.reduce((z,r)=>z+r.ecl,0)||1;
 return products.map((r,i)=>({...r,key:r.name,index:i,base:r.ecl,share:r.ecl/tot}));
}
function scenarioSegmentFactor(s,rows,i){
 if(s.pd*s.lgd===1)return 1;
 const multipliers=[.83,1.15,1.04,1.28],baseAvg=rows.reduce((z,r,j)=>z+r.share*multipliers[j],0)||1;
 return 1+(s.pd*s.lgd-1)*multipliers[i]/baseAvg;
}
function stressWaterfall(base,s){
 const impacts=scenarioImpactParts(base,s),final=base*s.pd*s.lgd;
 const items=[{name:'Base ECL',delta:base,start:0,end:base,kind:'total'}];
 let running=base;
 for(const p of impacts){items.push({name:p.label,delta:p.amount,start:running,end:running+p.amount,kind:p.amount>=0?'increase':'decrease'});running+=p.amount;}
 items.push({name:'Stressed ECL',delta:final,start:0,end:final,kind:'total'});
 const W=720,H=254,L=55,R=19,T=21,B=44,plotH=H-T-B;
 const ceiling=Math.max(1,base,final,...items.map(v=>v.end))*1.12;
 const x=(i)=>L+(i+.5)*(W-L-R)/items.length, y=v=>T+plotH*(1-v/ceiling),bw=Math.min(98,(W-L-R)/items.length*.52);
 let elements='';
 for(let i=0;i<=4;i++){let v=ceiling*i/4, yy=y(v);elements+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e7eceb"/><text x="${L-11}" y="${yy+3}" text-anchor="end" fill="#819099" font-size="11">€${num(v/1e6,1)}m</text>`;}
 for(let i=0;i<items.length;i++){
   const d=items[i],a=y(d.start),b=y(d.end),top=Math.min(a,b),height=Math.max(1,Math.abs(a-b)),color=d.kind==='total'?'#57788a':d.kind==='decrease'?'#64978a':'#aa7b89';
   elements+=`<rect x="${x(i)-bw/2}" y="${top}" width="${bw}" height="${height}" rx="1.5" fill="${color}" opacity=".96"><title>${d.name}: ${money(d.delta)}</title></rect>`;
   elements+=`<text x="${x(i)}" y="${Math.max(12,top-6)}" font-size="12" text-anchor="middle" fill="#3d5663">${d.kind==='total'?money(d.delta):(d.delta>0?'+':'')+money(d.delta)}</text>`;
   elements+=`<text x="${x(i)}" y="${H-B+20}" text-anchor="middle" font-size="11" fill="#728894">${d.name}</text>`;
   if(i<items.length-2)elements+=`<line x1="${x(i)+bw/2}" y1="${y(d.end)}" x2="${x(i+1)-bw/2}" y2="${y(d.end)}" stroke="#aab7bd" stroke-dasharray="3 3"/>`;
 }
 const legend=`<div class="stress-legend"><span><i style="background:#57788a"></i>Total</span><span><i style="background:#aa7b89"></i>Increase</span><span><i style="background:#64978a"></i>Decrease</span></div>`;
 return `${legend}<svg class="stress-waterfall" role="img" aria-label="Waterfall chart of base ECL, PD uplift, LGD uplift and stressed ECL" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">${elements}</svg>`;
}
function stressGeographic(s){
 const shock=stressFactor(s)-1;
 const rows=rowsByCountry().sort((a,b)=>b.ecl-a.ecl).slice(0,7);
 const total=rowsByCountry().reduce((z,r)=>z+r.ecl,0);
 const fullUplift=total*shock;
 const max=Math.max(...rows.map(r=>Math.abs(r.ecl*shock)),.001);
 return `<div class="stress-geo-header"><span>BOOKING COUNTRY</span><span>ECL UPLIFT</span><span>EUR</span><span>SHARE OF UPLIFT</span></div><div class="stress-geo-list">${rows.map(r=>{
 const delta=r.ecl*shock, share=fullUplift?delta/fullUplift*100:0;
 return `<div class="stress-geo-row"><span class="stress-country">${esc(r.name)}</span><span class="stress-geo-track"><span style="width:${shock?Math.max(1,Math.abs(delta)/max*100):0}%"></span></span><span class="stress-geo-money">${money(delta)}</span><span class="stress-share">${shock===0?'—':pc(share)}</span></div>`;
 }).join('')}</div><div class="stress-footnote">${shock===0?'Baseline contains no stress uplift. Select Adverse or Severe to inspect geographic contributions.':'Country contributions reconcile to the selected scenario uplift; ranking reflects expected-loss exposure.'}</div>`;
}
function stressSensitivityMatrix(){
 let rows=stressSegments(),cols=Object.keys(scenarios);
 return `<div class="stress-matrix-wrap"><table class="stress-matrix"><thead><tr><th>PRODUCT</th>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.name)}</td>${cols.map(c=>{
  let impact=(scenarioSegmentFactor(scenarios[c],rows,i)-1)*100;
  let t=Math.min(1,impact/115),opacity=(.07+.52*t).toFixed(2);
  return `<td class="${c===state.scenario?'scenario-selected':''}" style="background:rgba(158,101,120,${opacity})"><span>${pc(impact,1)}</span></td>`;
 }).join('')}</tr>`).join('')}</tbody></table><div class="stress-matrix-foot">Exposure-weighted scenario factors are normalised to the portfolio-level ECL multiplier.</div></div>`;
}
function stressSegmentComparison(s){
 const rows=stressSegments(); const W=650,H=213,L=48,R=10,T=17,B=47;const plotW=W-L-R,plotH=H-T-B;
 const vals=rows.map((r,i)=>({name:r.name,base:r.base,stressed:r.base*scenarioSegmentFactor(s,rows,i)}));
 const max=Math.max(1,...vals.flatMap(r=>[r.base,r.stressed]))*1.16;
 let html='';
 for(let i=0;i<=3;i++){const v=max*i/3,y=T+plotH*(1-v/max);html+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#e5ebe9"/><text x="${L-7}" y="${y+4}" font-size="10" text-anchor="end" fill="#87959b">€${num(v/1e6,1)}m</text>`;}
 vals.forEach((r,i)=>{
   const x=L+(i+.5)*plotW/vals.length, b0=T+plotH*(1-r.base/max),s0=T+plotH*(1-r.stressed/max),baseY=T+plotH;
   html+=`<rect x="${x-23}" y="${b0}" width="18" height="${baseY-b0}" fill="#597d90"><title>${r.name}, base ${money(r.base)}</title></rect>`;
   html+=`<rect x="${x+1}" y="${s0}" width="18" height="${baseY-s0}" fill="#ae8290"><title>${r.name}, stressed ${money(r.stressed)}</title></rect>`;
   html+=`<text x="${x}" y="${H-B+18}" text-anchor="middle" font-size="11" fill="#718691">${r.name}</text>`;
 });
 return `<div class="stress-legend"><span><i style="background:#597d90"></i>Base ECL</span><span><i style="background:#ae8290"></i>Stressed ECL</span></div><svg class="stress-segments-svg" role="img" aria-label="Base versus stressed expected credit loss by product" viewBox="0 0 ${W} ${H}">${html}</svg>`;
}
function stress(){
 const m=snapshot(),s=scenarios[state.scenario],factor=stressFactor(s),final=m.ecl*factor,inc=final-m.ecl;
 const buttons=Object.keys(scenarios).map(k=>`<button data-scenario="${k}" class="${k===state.scenario?'active':''}">${k}</button>`).join('');
 const scenariosCard=PANEL('Stress scenarios',`${s.label} · PD ×${num(s.pd,2)} · LGD ×${num(s.lgd,2)} · non-calibrated, deterministic sensitivity`,`<div class="scenario-tabs">${buttons}</div>`,'stress-selector');
 const tr=trend();const kpis=`<div class="grid kpi-grid">${kpiCard('Base ECL',money(m.ecl),'Reference expected loss',null,'○',tr.map(r=>r.ecl),'#708e9b')}${kpiCard('Stressed ECL',money(final),'PD × LGD sensitivity',null,'↗',tr.map(r=>r.ecl*factor),'#a77f8c','scenario')}${kpiCard('ECL uplift',money(inc),'Absolute scenario movement',null,'◈',[0,inc],'#7c92a0','scenario')}${kpiCard('Relative impact',pc((factor-1)*100),'Versus baseline',null,'↗',[0,(factor-1)*100],'#5f887c','scenario')}</div>`;
 const top=`<div class="grid equal-grid stress-main-row">${PANEL('Stress impact decomposition','Contribution of PD and LGD shocks to the change in expected credit loss',stressWaterfall(m.ecl,s),'stress-visual-panel')}${PANEL('Impact by geography','Expected-loss uplift by booking country',stressGeographic(s),'stress-visual-panel')}</div>`;
 const bottom=`<div class="grid equal-grid stress-bottom-row">${PANEL('Sensitivity matrix','ECL uplift by product and scenario versus baseline',stressSensitivityMatrix(),'stress-visual-panel')}${PANEL('Portfolio response by segment','Base and scenario-adjusted ECL by lending product',stressSegmentComparison(s),'stress-visual-panel')}</div>`;
 return `${scenariosCard}${kpis}${top}${bottom}`;
}

function loanRows(){let search=state.search.toLowerCase().trim();return DB.loans.filter(l=>(state.product==='All'||l.Product===state.product)&&(state.region==='Global'||l.RegionGroup===state.region)&&(!state.country||l.CountryCode===state.country)&&(!search||Object.values(l).some(v=>String(v).toLowerCase().includes(search))))}
function loanExplorer(){let rows=loanRows(),n=Math.max(6,Math.min(23,Math.floor((window.innerHeight-410)/34))),totalPages=Math.max(1,Math.ceil(rows.length/n));state.loanPage=Math.max(0,Math.min(totalPages-1,state.loanPage));let slice=rows.slice(state.loanPage*n,(state.loanPage+1)*n);
 return PANEL('International loan sample','Illustrative rows across 28 markets; not the full book and not additive to aggregate exposures',`<div class="loan-toolbar"><input id="loan-search" placeholder="Search loan, country, product or rating" value="${esc(state.search)}" autocomplete="off"><span class="loan-count">${rows.length} facilities · ${state.loanPage+1} / ${totalPages}</span></div><div class="table-outer"><table class="loan-table"><thead><tr><th>Loan</th><th>Country</th><th>Product</th><th>Exposure</th><th>PD</th><th>Rating</th><th>Stage</th><th>DPD</th><th>Vintage</th></tr></thead><tbody>${slice.map(l=>`<tr><td>${esc(l.LoanId)}</td><td>${esc(l.Country)}</td><td>${esc(l.Product)}</td><td>${money(l.ExposureEUR)}</td><td>${pc(l.PDPercent,2)}</td><td><span class="pill ${l.Grade==='D'?'risk':''}">${l.Grade}</span></td><td>${l.Stage}</td><td>${l.DPD}</td><td>${l.Vintage}</td></tr>`).join('')}</tbody></table></div><div class="pager"><button data-loan-page="prev">Previous</button><span>Page ${state.loanPage+1} of ${totalPages}</span><button data-loan-page="next">Next</button></div>`,'large-panel')}
function updateUI(){document.body.classList.add('viewport-mode');document.body.dataset.currentView=state.page;document.body.classList.toggle('overview-mode',state.page==='overview');let [title,subtitle]=PAGES[state.page];$('#title').textContent=title;$('#subtitle').textContent=subtitle;$('#context').textContent='RISK MANAGEMENT  /  '+(state.country?COUNTRY_BY_CODE[state.country]?.name:state.region.toUpperCase());$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));let badge=$('#country-badge');badge.hidden=!state.country;badge.textContent=state.country?(COUNTRY_BY_CODE[state.country]?.name+' ×'):'';
 $('#dashboard').innerHTML=({overview,portfolio,credit:quality,stress,loans:loanExplorer})[state.page]();}
function init(){let select=$('#product');DB.domestic.products.forEach(p=>select.add(new Option(p,p)));select.value=state.product;$('#region').value=state.region;$('#period').value='12';updateUI()}
function exportData(){let rows=baseSlice();let fields=['date','country','country_name','product','exposure','npl','ecl','loans'];let csv=[fields.join(';'),...rows.map(r=>fields.map(k=>String(r[k])).join(';'))].join('\r\n');let file=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download='HBC_Credit_Portfolio_'+LATEST+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{let tab=e.target.closest('[data-page]');if(tab){state.page=tab.dataset.page;updateUI();return}let r=e.target.closest('[data-country]');if(r){let iso=r.dataset.country;if(COUNTRY_BY_CODE[iso]){state.country=state.country===iso?null:iso;state.region='Global';$('#region').value='Global';updateUI()}return}let metric=e.target.closest('[data-mapmetric]');if(metric){state.mapMetric=metric.dataset.mapmetric;updateUI();return}let scenario=e.target.closest('[data-scenario]');if(scenario){state.scenario=scenario.dataset.scenario;updateUI();return}let pagination=e.target.closest('[data-loan-page]');if(pagination){state.loanPage+=pagination.dataset.loanPage==='prev'?-1:1;updateUI();return}if(e.target.id==='country-badge'){state.country=null;updateUI();return}});
document.addEventListener('change',e=>{if(e.target.id==='product'){state.product=e.target.value;state.loanPage=0;updateUI()}if(e.target.id==='region'){state.region=e.target.value;state.country=null;state.loanPage=0;updateUI()}if(e.target.id==='period'){state.period=+e.target.value;updateUI()}});
document.addEventListener('input',e=>{if(e.target.id==='loan-search'){let q=e.target.value, pos=e.target.selectionStart;state.search=q;state.loanPage=0;updateUI();let inp=$('#loan-search');inp?.focus();inp?.setSelectionRange(pos,pos)}});
$('#reset').addEventListener('click',()=>{Object.assign(state,{product:'All',region:'Global',country:null,period:12,mapMetric:'exposure',scenario:'Baseline',search:'',loanPage:0});$('#product').value='All';$('#region').value='Global';$('#period').value='12';updateUI()});$('#export').addEventListener('click',exportData);
init();

return {
  updateSemantic: function(tableData){
    if(!tableData || !tableData.length) return;
    const metrics=['exposure','npl','ecl','stage2','stage3','dpd30','scheduled','received','loans'];
    const updated=[];
    for(const r of tableData){
      if(!r.date || !r.country || !r.product) continue;
      let o={
        date:String(r.date).slice(0,7),
        country:String(r.country),
        country_name:String(r.country_name),
        region_group:String(r.region_group),
        product:String(r.product)
      };
      for(const k of metrics) o[k]=Number(r[k])||0;
      updated.push(o);
    }
    if(updated.length){
      DB.fact=updated;
      const label=document.querySelector('.demo-label');
      if(label) label.textContent='POWER BI SEMANTIC MODEL · LIVE';
      updateUI();
    }
  }
};

}
function Visual(options){
  this.el=options.element;
  this.el.style.overflow='hidden';
  this.el.style.background='#f2f1ee';
  this.el.classList.add('hbc-powerbi-host');
  try {
    this.el.innerHTML=MARKUP;
    if(!document.getElementById('hbc-risk-style')){
      var st=document.createElement('style');st.id='hbc-risk-style';st.textContent=STYLE;document.head.appendChild(st);
    }
    this.bridge=setupDashboard();
  } catch(err){
    this.bridge=null;
    this.el.innerHTML='<div style="padding:22px;font:14px Segoe UI,Arial,sans-serif;color:#243644;background:#fcfbf9">HBC Bank · Visual initialization error: '+String(err&&err.message||err).replace(/[<>&"]/g,'')+'</div>';
    if(window.console&&console.error)console.error('HBC Bank initialization',err);
  }
}
Visual.prototype.update=function(options){
  var vp=options.viewport||{};
  if(vp.width) this.el.style.width=vp.width+'px';
  if(vp.height) this.el.style.height=vp.height+'px';
  var dataView=options.dataViews&&options.dataViews[0];
  var facts=parseDataView(dataView);
  if(facts && facts.length && this.bridge) {
    try { this.bridge.updateSemantic(facts); }
    catch(err) { if(console&&console.error)console.error('HBC Bank DataView',err); }
  }
};
var plugin = {
 name: PLUGIN_GUID,
 displayName: 'HBC Bank | Credit Risk Intelligence',
 class: 'Visual',
 apiVersion: '5.8.0',
 create: function(opts){ return new Visual(opts); },
 custom: true
};
var p=window.powerbi;
if(p){
 p.visuals=p.visuals||{};
 p.visuals.plugins=p.visuals.plugins||{};
 p.visuals.plugins[PLUGIN_GUID]=plugin;
}
return {default: plugin};
})();
